                <script nonce="<?php echo htmlspecialchars($_SESSION['_csp_nonce'] ?? ''); ?>">
                (function () {
                  var box = document.getElementById('heroFlow');
                  if (!box) return;
                  var items = Array.prototype.slice.call(box.querySelectorAll('.hf-m'));
                  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
                  box.classList.add('js');
                  var MAX = 4, TYPE = 1100, GAP = 900, HOLD = 3200, shown = [], idx = 0;
                  function reveal(el) {
                    el.classList.add('show');
                    shown.push(el);
                    if (shown.length > MAX) { shown.shift().classList.remove('show'); }
                  }
                  function next() {
                    if (idx >= items.length) {
                      setTimeout(function () {
                        shown.forEach(function (el) { el.classList.remove('show'); });
                        shown = []; idx = 0; setTimeout(next, 700);
                      }, HOLD);
                      return;
                    }
                    var el = items[idx++];
                    if (!el.classList.contains('hf-row')) { reveal(el); setTimeout(next, GAP + 600); return; }
                    // show a three-dot typing bubble on the sender's side first
                    var t = document.createElement('div');
                    t.className = 'hf-row hf-m show hf-typing-row ' + (el.classList.contains('hf-out') ? 'hf-out' : 'hf-in');
                    t.innerHTML = '<div class="hf-bubble hf-typing"><span></span><span></span><span></span></div>';
                    box.insertBefore(t, el);
                    setTimeout(function () {
                      box.removeChild(t);
                      reveal(el);
                      setTimeout(next, GAP);
                    }, TYPE);
                  }
                  next();
                })();
                </script>
            </div>

            </div>

