                    <?php foreach ($__hub as $i => $n): if ($n[0] !== 'R') continue; ?>
                    <button type="button" class="fh-node" data-i="<?php echo $i; ?>" aria-pressed="false"><span class="fh-nl"><?php echo $__esc($n[2]); ?></span><span class="fh-nic"><?php echo $__svg($n[1]); ?></span></button>
