                </div>
                <div class="fh-d-right">
                    <span class="fh-live">LIVE IN THE CHAT</span>
                    <div class="fh-msg fh-msg-in" id="fhMsgIn"></div>
                    <div class="fh-msg fh-msg-out" id="fhMsgOut"></div>
                    <span class="fh-chip" id="fhChip"></span>
                </div>
            </div>
        </div>
        <script nonce="<?php echo htmlspecialchars($_SESSION['_csp_nonce'] ?? ''); ?>">
        (function () {
          var DATA = <?php echo json_encode(array_map(static fn($n) => ['icon' => $__svg($n[1]), 'title' => $n[2], 'tag' => $n[3], 'desc' => $n[4], 'in' => $n[5], 'out' => $n[6], 'c1' => $n[7][0], 'c2' => $n[7][1], 'chip' => $n[8]], $__hub), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>;
          var root = document.getElementById('featHub'); if (!root) return;
          var stage = root.querySelector('.fh-stage'), svg = root.querySelector('.fh-lines'), hub = root.querySelector('.fh-hub');
          var nodes = Array.prototype.slice.call(root.querySelectorAll('.fh-node'));
          var cur = 0, timer = null, NS = 'http://www.w3.org/2000/svg';
          function $(id) { return document.getElementById(id); }
          function draw() {
            while (svg.firstChild) svg.removeChild(svg.firstChild);
            if (window.innerWidth <= 760) return;
            var sb = stage.getBoundingClientRect(), hb = hub.getBoundingClientRect();
            svg.setAttribute('viewBox', '0 0 ' + sb.width + ' ' + sb.height);
            var hx = hb.left - sb.left + hb.width / 2, hy = hb.top - sb.top + hb.height / 2, r = hb.width / 2;
            nodes.forEach(function (nd) {
              var b = nd.getBoundingClientRect(), left = nd.parentNode.classList.contains('fh-left');
              var x1 = left ? b.right - sb.left : b.left - sb.left, y1 = b.top - sb.top + b.height / 2;
              var x2 = left ? hx - r + 2 : hx + r - 2, y2 = hy, mx = (x1 + x2) / 2;
              var p = document.createElementNS(NS, 'path');
              p.setAttribute('d', 'M' + x1 + ' ' + y1 + ' C' + mx + ' ' + y1 + ' ' + mx + ' ' + y2 + ' ' + x2 + ' ' + y2);
              p.setAttribute('class', 'fh-path' + (+nd.dataset.i === cur ? ' is-on' : ''));
              svg.appendChild(p);
            });
          }
          function show(i) {
            cur = i; var d = DATA[i];
            nodes.forEach(function (n) { var on = +n.dataset.i === i; n.classList.toggle('is-on', on); n.setAttribute('aria-pressed', on); });
            $('fhIc').innerHTML = d.icon; $('fhTitle').textContent = d.title; $('fhTag').textContent = d.tag;
            $('fhDesc').textContent = d.desc; $('fhIn').textContent = d.in; $('fhOut').textContent = d.out;
            $('fhMsgIn').textContent = d.c1; $('fhMsgOut').textContent = d.c2; $('fhChip').textContent = d.chip;
            var dt = root.querySelector('.fh-detail'); dt.classList.remove('fh-swap'); void dt.offsetWidth; dt.classList.add('fh-swap');
            draw();
          }
          function auto() { clearInterval(timer); timer = setInterval(function () { show((cur + 1) % DATA.length); }, 5200); }
          nodes.forEach(function (n) { n.addEventListener('click', function () { show(+n.dataset.i); auto(); }); });
          window.addEventListener('resize', draw);
          if (window.ResizeObserver) new ResizeObserver(draw).observe(stage);
          show(0);
          if (!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)) auto();
        })();
        </script>
    </div>
</section>

