.sync-feat-check svg{width:11px;height:11px;stroke:white;stroke-width:3;fill:none}
/* ── Right: exact-crop layer system ── */
/* Bounding boxes (scanned at 2px step, 1024×1038 canvas):
   1.png phone+deco: x=30–988, y=0–962  (full canvas, base layer)
   2.png girl card:  x=296–850 (554w), y=318–792 (474h)
   3.png notif card: x=104–582 (478w), y=174–368 (194h)
   4.png buy-now:    x=406–694 (288w), y=420–506 (86h)
*/
.sync-right{position:relative;display:flex;align-items:center;justify-content:center}
.sv-wrap{position:relative;width:100%;max-width:620px;aspect-ratio:1024/1038}
/* Base phone image — full canvas, z=1 */
.sv-base{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:fill;z-index:1;display:block}
/* Crop containers: clip to exact content bbox so NO white canvas bleeds onto other layers */
.sv-crop{position:absolute;overflow:hidden}
.sv-crop img{position:absolute;display:block}

/* — GIRL (2.png) z=4: x=296–850(554w) y=318–792(474h) — */
.sv-crop-girl{
    left:calc(296/1024*100%); top:calc(318/1038*100%);
    width:calc(554/1024*100%); height:calc(474/1038*100%);
    z-index:4; animation:svGirlFloat 4s ease-in-out infinite;
    filter:drop-shadow(0 24px 48px rgba(0,0,0,.18));
}
.sv-crop-girl img{
    width:calc(1024/554*100%); height:calc(1038/474*100%);
    left:calc(-296/554*100%); top:calc(-318/474*100%);
}

/* — NOTIF CARD (3.png) z=3: x=104–582(478w) y=174–368(194h) — */
.sv-crop-notif{
    left:calc(104/1024*100%); top:calc(174/1038*100%);
    width:calc(478/1024*100%); height:calc(194/1038*100%);
    z-index:3; animation:svNotifFloat 3.5s ease-in-out infinite;
    filter:drop-shadow(0 12px 32px rgba(0,0,0,.14));
    background:#ffffff; /* card body is transparent in PNG — restore white */
    border-radius:14px;
}
.sv-crop-notif img{
    width:calc(1024/478*100%); height:calc(1038/194*100%);
    left:calc(-104/478*100%); top:calc(-174/194*100%);
}

/* — BUY NOW (4.png) z=2: x=406–694(288w) y=420–506(86h) — */
.sv-crop-btn{
    left:calc(406/1024*100%); top:calc(420/1038*100%);
    width:calc(288/1024*100%); height:calc(86/1038*100%);
    z-index:2; animation:svBtnFloat 3.8s ease-in-out infinite;
    filter:drop-shadow(0 8px 20px rgba(0,0,0,.12));
}
.sv-crop-btn img{
    width:calc(1024/288*100%); height:calc(1038/86*100%);
    left:calc(-406/288*100%); top:calc(-420/86*100%);
}

@keyframes svGirlFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
@keyframes svNotifFloat{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-8px) rotate(-1deg)}}
@keyframes svBtnFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@media(max-width:900px){
    .sync-grid{grid-template-columns:1fr}
