    $testimonials = cms_testimonials();
    $__tcPin = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/></svg>';
    $__tcTicks = '<svg width="16" height="11" viewBox="0 0 16 11" fill="none" stroke="#53bdeb" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 6 4 9 10 2"/><polyline points="6 8 7.5 9 14 2"/></svg>';
    $__tcCard = static function (array $t) use ($__tcPin, $__tcTicks): string {
        [$init, $name, $role, $av, $stars, $text] = $t;
        $city = trim((string)substr(strrchr($role, ','), 1));
        $job  = trim(preg_replace('/,[^,]*$/', '', $role));
        $h  = '<article class="tc-card"><div class="tc-head"><div class="cust-av ' . $av . '">' . htmlspecialchars($init) . '</div>';
        $h .= '<div class="tc-who"><strong>' . htmlspecialchars($name) . '</strong><span>' . htmlspecialchars($job) . '</span></div>';
        $h .= '<span class="tc-city">' . $__tcPin . htmlspecialchars($city) . '</span></div>';
        $h .= '<p>' . htmlspecialchars($text) . '</p><div class="tc-foot"><span class="tc-stars">' . str_repeat('★', (int)$stars) . str_repeat('☆', 5 - (int)$stars) . '</span>';
        $h .= '<span class="tc-read">' . $__tcTicks . 'VERIFIED CUSTOMER</span></div></article>';
        return $h;
    };
    $__tcRow = static function (array $items, string $cls) use ($__tcCard): string {
        $one = '';
        foreach ($items as $t) { $one .= $__tcCard($t); }
        return '<div class="tc-row ' . $cls . '"><div class="tc-track">' . $one . '</div><div class="tc-track" aria-hidden="true">' . $one . '</div></div>';
    };
    $__n = count($testimonials);
    $__shift = array_merge(array_slice($testimonials, (int)ceil($__n / 2)), array_slice($testimonials, 0, (int)ceil($__n / 2)));
    ?>
    <div class="tc-stage">
        <?php echo $__tcRow($testimonials, 'tc-left'); ?>
        <?php echo $__tcRow($__shift, 'tc-right'); ?>
    </div>
</section>

