<script nonce="<?php echo htmlspecialchars($_SESSION['_csp_nonce'] ?? ''); ?>">
document.addEventListener('DOMContentLoaded', () => {
    const achObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.querySelectorAll('.count-up').forEach(el => {
                    const target = parseInt(el.dataset.val);
                    if (target === 0) { el.textContent = '0'; return; }
                    let current = 0;
                    const inc = Math.max(1, Math.ceil(target / 60));
                    const timer = setInterval(() => {
                        current = Math.min(current + inc, target);
                        el.textContent = current;
                        if (current >= target) clearInterval(timer);
                    }, 25);
                });
                achObserver.unobserve(entry.target);
            }
        });
    }, { threshold: 0.4 });
    const achStrip = document.querySelector('.trust-strip');
    if (achStrip) achObserver.observe(achStrip);

    const phoneMessages = document.querySelectorAll('.wa-msg:not(.visible), .wa-ai-tag:not(.visible)');
    phoneMessages.forEach((msg, i) => {
        setTimeout(() => { msg.classList.add('visible'); }, 300 + (i * 900));
    });

    const showcaseTabs = document.querySelectorAll('.stab');
    showcaseTabs.forEach(tab => {
        tab.addEventListener('click', () => {
            showcaseTabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            const panelId = tab.dataset.tab;
            document.querySelectorAll('.spanel').forEach(p => p.classList.remove('active'));
            const panel = document.getElementById('tab-' + panelId);
            if (panel) panel.classList.add('active');
            if (panelId === 'ai') animateAIChat();
            if (panelId === 'campaigns') animateCampaignCount();
        });
    });

    function animateAIChat() {
        const msgs = document.querySelectorAll('#tab-ai .acp-msg, #tab-ai .acp-ai-badge');
        msgs.forEach(m => { m.classList.remove('show'); m.style.opacity = '0'; });
        msgs.forEach((m, i) => setTimeout(() => m.classList.add('show'), i * 700));
    }

    function animateCampaignCount() {
        document.querySelectorAll('.anim-count[data-target]').forEach(el => {
            let n = 0;
            const target = parseInt(el.dataset.target);
            if (!target) return;
            const step = Math.ceil(target / 60);
            const t = setInterval(() => {
                n = Math.min(n + step, target);
                el.textContent = n.toLocaleString('en-IN');
                if (n >= target) clearInterval(t);
            }, 20);
        });
    }

        setTimeout(() => animateAIChat(), 800);

    // Industry tabs — animated chat messages + auto-cycle
    var itabBtns = document.querySelectorAll('.itab-btn');
    var itabs = Array.from(itabBtns);
    var itabIdx = 0, itabTimer = null, itabPaused = false, msgTimers = [];
    var ITAB_MS = 6000;

    var itConvos = {
        ecommerce:[
            {d:350,t:'out',text:'Cart status',time:'4:12 PM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Hi Riya! You left <strong>3 items</strong> in cart!',qr:['Pay &#8377;1,299','View Cart'],time:'4:12 PM'},
            {d:750,t:'out',text:'Pay &#8377;1,299',time:'4:13 PM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Your Order',rows:['Nike Sneakers &mdash; <span class="it-hi">&#8377;799</span>','Earbuds &mdash; <span class="it-hi">&#8377;299</span>','Phone Case &mdash; <span class="it-hi">&#8377;199</span>'],time:'4:13 PM'},
            {d:700,t:'in',text:'Payment link sent! Track order here.',time:'4:14 PM'}
        ],
        education:[
            {d:350,t:'out',text:'Admission',time:'9:30 AM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Hi! Admissions open 2024&ndash;25. Which class?',qr:['Class 6&ndash;8','Class 9&ndash;10','Class 11&ndash;12'],time:'9:30 AM'},
            {d:750,t:'out',text:'Class 9&ndash;10',time:'9:31 AM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Admission Details',rows:['Fee: <span class="it-hi">&#8377;42,000/yr</span>','Last Date: July 20','Docs: Aadhaar, TC'],time:'9:31 AM'},
            {d:700,t:'in',text:'Apply online or schedule a visit?',qr:['Apply','Visit'],time:'9:32 AM'}
        ],
        healthcare:[
            {d:350,t:'out',text:'Book appointment',time:'11:05 AM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Hi! Which department?',qr:['General','Dental','Ortho'],time:'11:05 AM'},
            {d:750,t:'out',text:'Dental',time:'11:06 AM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Available Slots',rows:['Dr. Priya &mdash; Tue 10:00 AM','Dr. Arjun &mdash; Wed 2:00 PM','Dr. Meena &mdash; Thu 4:30 PM'],time:'11:06 AM'},
            {d:700,t:'in',text:'Dr. Priya Tue 10 AM. Confirm?',qr:['Confirm','Other Slots'],time:'11:07 AM'}
        ],
        realestate:[
            {d:350,t:'out',text:'3BHK Flat Powai',time:'2:15 PM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Budget range for Powai 3BHK?',qr:['&#8377;80L&ndash;1Cr','&#8377;1&ndash;1.5Cr','&#8377;1.5Cr+'],time:'2:15 PM'},
            {d:750,t:'out',text:'&#8377;1&ndash;1.5Cr',time:'2:16 PM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Powai Listings',rows:['Hiranandani &mdash; <span class="it-hi">&#8377;1.5Cr</span>','Seasons Ave &mdash; <span class="it-hi">&#8377;1.2Cr</span>','Green Valley &mdash; <span class="it-hi">&#8377;98L</span>'],time:'2:16 PM'},
            {d:700,t:'in',text:'Agent call or site visit?',qr:['Call Agent','Site Visit'],time:'2:17 PM'}
        ],
        restaurant:[
            {d:350,t:'out',text:'Table booking',time:'7:10 PM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Welcome! How many guests?',qr:['2 Persons','4 Persons','Group 8+'],time:'7:10 PM'},
            {d:750,t:'out',text:'4 Persons',time:'7:11 PM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Available Slots',rows:['Today 7:30 PM &mdash; Table 5','Today 8:00 PM &mdash; Table 3','Today 9:00 PM &mdash; Table 7'],time:'7:11 PM'},
            {d:700,t:'in',text:'Table for 4 at <strong>7:30 PM</strong> confirmed!',time:'7:12 PM'}
        ],
        salon:[
            {d:350,t:'out',text:'Book service',time:'3:20 PM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Hi Priya! Choose your service:',qr:['Haircut','Facial','Spa'],time:'3:20 PM'},
            {d:750,t:'out',text:'Facial',time:'3:21 PM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Choose Stylist',rows:['Kavya &mdash; Gold <span class="it-hi">&#8377;899</span>','Meera &mdash; Herbal <span class="it-hi">&#8377;699</span>','Nisha &mdash; Glow <span class="it-hi">&#8377;799</span>'],time:'3:21 PM'},
            {d:700,t:'in',text:'Reminder set for tomorrow 11 AM!',time:'3:22 PM'}
        ],
        automobile:[
            {d:350,t:'out',text:'Service status',time:'10:00 AM'},
            {d:700,t:'type'},
            {d:1300,t:'in',lbl:'Waamini',text:'Hi Kiran! Swift due in <strong>3 days</strong>. Book?',qr:['Book Now','Remind Later'],time:'10:00 AM'},
            {d:750,t:'out',text:'Book Now',time:'10:01 AM'},
            {d:650,t:'type'},
            {d:1000,t:'list',head:'Service Package',rows:['Oil Change &mdash; <span class="it-hi">&#8377;799</span>','Tire Rotation &mdash; <span class="it-hi">&#8377;299</span>','AC Service &mdash; <span class="it-hi">&#8377;499</span>'],time:'10:01 AM'},
            {d:700,t:'in',text:'Booked: Tue 10 AM, Waamini Motors Powai.',time:'10:02 AM'}
        ]
    };

    function clearMsgTimers(){msgTimers.forEach(clearTimeout);msgTimers=[];}

    function mkMsgEl(m){
        var el=document.createElement('div');
        if(m.t==='out'){
            el.className='it-row it-out';
            el.innerHTML='<div class="it-bbl">'+m.text+'</div><div class="it-meta">'+m.time+' <span class="it-ticks">&#10003;&#10003;</span></div>';
        } else if(m.t==='in'){
            el.className='it-row it-in';
            var h='<div class="it-bbl">';
            if(m.lbl)h+='<span class="it-lbl">'+m.lbl+'</span>';
            h+=m.text+'</div>';
            if(m.qr&&m.qr.length)h+='<div class="it-qr-row">'+m.qr.map(function(q){return'<span class="it-qr">'+q+'</span>';}).join('')+'</div>';
            h+='<div class="it-meta">'+m.time+'</div>';
            el.innerHTML=h;
        } else if(m.t==='list'){
            el.className='it-list';
            el.innerHTML='<div class="it-list-head">'+m.head+'</div>'+
                m.rows.map(function(r){return'<div class="it-list-row">'+r+'</div>';}).join('')+
                '<div class="it-meta" style="padding:4px 8px 5px;">'+m.time+'</div>';
        }
        return el;
    }

    function runConvo(chatEl, msgs){
        clearMsgTimers();
        chatEl.innerHTML='<div class="it-date">Today</div>';
        var cum=0;
        msgs.forEach(function(m){
            cum+=m.d;
            (function(delay,msg){
                msgTimers.push(setTimeout(function(){
                    var typ=chatEl.querySelector('.it-typing');
                    if(typ)typ.parentNode.removeChild(typ);
                    if(msg.t==='type'){
                        var te=document.createElement('div');
                        te.className='it-typing';
                        te.innerHTML='<div class="it-typing-bubble"><span></span><span></span><span></span></div>';
                        chatEl.appendChild(te);
                    } else {
                        var el=mkMsgEl(msg);
                        el.style.opacity='0';
                        el.style.transform='translateY(6px)';
                        el.style.transition='opacity 0.3s ease,transform 0.3s ease';
                        chatEl.appendChild(el);
                        requestAnimationFrame(function(){el.style.opacity='1';el.style.transform='translateY(0)';});
                    }
                    chatEl.scrollTop=chatEl.scrollHeight;
                },delay));
            })(cum,m);
        });
    }

    function itabSwitch(idx){
        itabs.forEach(function(b){b.classList.remove('active');});
        document.querySelectorAll('.itab-panel').forEach(function(p){p.classList.remove('active');});
        void itabs[idx].offsetWidth;
        itabs[idx].classList.add('active');
        var key=itabs[idx].getAttribute('data-Industrytab');
        var panel=document.getElementById('IndustryTab-'+key);
        if(panel){
            panel.classList.add('active');
            var chatEl=document.getElementById('itchat-'+key);
            if(chatEl&&itConvos[key])runConvo(chatEl,itConvos[key]);
        }
    }

    function itabNext(){if(itabPaused)return;itabIdx=(itabIdx+1)%itabs.length;itabSwitch(itabIdx);}
    function itabReset(){clearInterval(itabTimer);itabTimer=setInterval(itabNext,ITAB_MS);}

    itabs.forEach(function(btn,i){
        btn.addEventListener('click',function(){itabIdx=i;itabSwitch(i);itabReset();});
    });

    var itabSection=document.querySelector('.industry-tabs-section');
    if(itabSection){
        itabSection.addEventListener('mouseenter',function(){itabPaused=true;});
        itabSection.addEventListener('mouseleave',function(){itabPaused=false;});
    }

    itabSwitch(0);
    itabReset();

    // AI Showcase chat animation
    const aiShowcaseObs = new IntersectionObserver((entries) => {
        entries.forEach(e => {
            if (e.isIntersecting) {
                const msgs = e.target.querySelectorAll('.ai-sc-msg, .ai-sc-badge');
                msgs.forEach(m => { m.classList.remove('show'); m.style.opacity = '0'; });
                msgs.forEach((m, i) => setTimeout(() => m.classList.add('show'), i * 800));
                aiShowcaseObs.unobserve(e.target);
            }
        });
    }, { threshold: 0.3 });
    const aiCard = document.querySelector('.ai-showcase-card');
    if (aiCard) aiShowcaseObs.observe(aiCard);

    const showcaseObs = new IntersectionObserver((entries) => {
        entries.forEach(e => {
            if (e.isIntersecting) {
                animateCampaignCount();
                showcaseObs.unobserve(e.target);
            }
        });
    }, { threshold: 0.3 });
    const showcase = document.querySelector('.showcase-section');
    if (showcase) showcaseObs.observe(showcase);

    document.querySelectorAll('.faq-q').forEach(q => {
        q.addEventListener('click', function() {
            const item = this.parentElement;
            const isActive = item.classList.contains('active');
            document.querySelectorAll('.faq-item').forEach(f => f.classList.remove('active'));
            if (!isActive) item.classList.add('active');
        });
    });
});
</script>

